+
+void DirLister::syncExtraItems(bool refresh)
+{
+    if (!isFinished() || url().isEmpty()) {
+        return;
+    }
+
+    auto findByUrl = [](const KFileItemList &items, const QUrl &url) {
+        return std::find_if(items.cbegin(), items.cend(), [&url](const KFileItem &item) {
+            return item.url() == url;
+        });
+    };
+
+    KFileItemList removed;
+    QList<QPair<KFileItem, KFileItem>> changed;
+    KFileItemList added;
+
+    for (const KFileItem &item : std::as_const(m_shownExtraItems)) {
+        const auto it = findByUrl(m_extraItems, item.url());
+        if (it == m_extraItems.cend()) {
+            removed.append(item);
+        } else if (refresh) {
+            changed.append({item, *it});
+        }
+    }
+
+    for (const KFileItem &item : std::as_const(m_extraItems)) {
+        if (findByUrl(m_shownExtraItems, item.url()) == m_shownExtraItems.cend()) {
+            added.append(item);
+        }
+    }
+
+    m_shownExtraItems = m_extraItems;
+
+    if (!removed.isEmpty()) {
+        Q_EMIT itemsDeleted(removed);
+    }
+    if (!changed.isEmpty()) {
+        Q_EMIT refreshItems(changed);
+    }
+    if (!added.isEmpty()) {
+        Q_EMIT itemsAdded(url(), added);
+    }
 }

