+void FolderModel::setShowDevices(bool enable)
+{
+    if (m_showDevices == enable) {
+        return;
+    }
+
+    m_showDevices = enable;
+
+    if (enable && !m_placesModel) {
+        m_placesModel = new KFilePlacesModel(this);
+        connect(m_placesModel, &QAbstractItemModel::rowsInserted, this, &FolderModel::updateDeviceItems);
+        connect(m_placesModel, &QAbstractItemModel::rowsRemoved, this, &FolderModel::updateDeviceItems);
+        connect(m_placesModel, &QAbstractItemModel::dataChanged, this, &FolderModel::updateDeviceItems);
+        connect(m_placesModel, &QAbstractItemModel::modelReset, this, &FolderModel::updateDeviceItems);
+        connect(m_placesModel, &KFilePlacesModel::setupDone, this, [this](const QModelIndex &index, bool success) {
+            const QString udi = m_placesModel->deviceForIndex(index).udi();
+            if (m_devicesToOpen.remove(udi) && success) {
+                auto job = new KIO::OpenUrlJob(m_placesModel->url(index));
+                job->setUiDelegate(KIO::createDefaultJobUiDelegate(KJobUiDelegate::AutoHandlingEnabled, nullptr));
+                job->start();
+            }
+        });
+    }
+
+    updateDeviceItems();
+
+    Q_EMIT showDevicesChanged();
+}
+
+void FolderModel::updateDeviceItems()
+{
+    KFileItemList items;
+    m_deviceUdis.clear();
+
+    for (int row = 0; m_showDevices && row < m_placesModel->rowCount(); ++row) {
+        const QModelIndex index = m_placesModel->index(row, 0);
+        const KFilePlacesModel::GroupType group = m_placesModel->groupType(index);
+
+        if (!m_placesModel->isDevice(index) || m_placesModel->isHidden(index)
+            || (group != KFilePlacesModel::DevicesType && group != KFilePlacesModel::RemovableDevicesType)) {
+            continue;
+        }
+
+        const QString udi = m_placesModel->deviceForIndex(index).udi();
+        const bool mounted = !m_placesModel->setupNeeded(index);
+
+        QUrl url;
+        url.setScheme(s_deviceScheme);
+        url.setPath(QLatin1Char('/') + QString(udi).replace(QLatin1Char('/'), QLatin1Char('_')));
+
+        KIO::UDSEntry entry;
+        entry.fastInsert(KIO::UDSEntry::UDS_NAME, url.fileName());
+        entry.fastInsert(KIO::UDSEntry::UDS_DISPLAY_NAME, m_placesModel->text(index));
+        entry.fastInsert(KIO::UDSEntry::UDS_ICON_NAME, index.data(KFilePlacesModel::IconNameRole).toString());
+
+        if (mounted) {
+            // Open, preview and accept drops on the place the device is mounted at
+            entry.fastInsert(KIO::UDSEntry::UDS_FILE_TYPE, S_IFDIR);
+            entry.fastInsert(KIO::UDSEntry::UDS_ACCESS, 0700);
+            entry.fastInsert(KIO::UDSEntry::UDS_MIME_TYPE, QStringLiteral("inode/directory"));
+            entry.fastInsert(KIO::UDSEntry::UDS_TARGET_URL, m_placesModel->url(index).toString());
+        } else {
+            entry.fastInsert(KIO::UDSEntry::UDS_FILE_TYPE, S_IFBLK);
+            entry.fastInsert(KIO::UDSEntry::UDS_MIME_TYPE, QStringLiteral("inode/blockdevice"));
+        }
+
+        items.append(KFileItem(entry, url));
+        m_deviceUdis.insert(url, udi);
+    }
+
+    static_cast<DirLister *>(m_dirModel->dirLister())->setExtraItems(items);
+}
+
+QModelIndex FolderModel::placesIndexForDevice(const KFileItem &item) const
+{
+    const QString udi = m_deviceUdis.value(item.url());
+
+    if (udi.isEmpty()) {
+        return {};
+    }
+
+    for (int row = 0; row < m_placesModel->rowCount(); ++row) {
+        const QModelIndex index = m_placesModel->index(row, 0);
+        if (m_placesModel->isDevice(index) && m_placesModel->deviceForIndex(index).udi() == udi) {
+            return index;
+        }
+    }
+
+    return {};
+}
+
+void FolderModel::openDevice(const KFileItem &item)
+{
+    const QModelIndex index = placesIndexForDevice(item);
+
+    if (!index.isValid()) {
+        return;
+    }
+
+    if (m_placesModel->setupNeeded(index)) {
+        m_devicesToOpen.insert(m_placesModel->deviceForIndex(index).udi());
+        m_placesModel->requestSetup(index);
+        return;
+    }
+
+    auto job = new KIO::OpenUrlJob(m_placesModel->url(index));
+    job->setUiDelegate(KIO::createDefaultJobUiDelegate(KJobUiDelegate::AutoHandlingEnabled, nullptr));
+    job->start();
+}
+
+void FolderModel::addDeviceActions(QMenu *menu, const KFileItem &item)
+{
+    const QModelIndex index = placesIndexForDevice(item);
+
+    if (!index.isValid()) {
+        return;
+    }
+
+    QAction *open = menu->addAction(QIcon::fromTheme(QStringLiteral("document-open")), i18n("&Open"));
+    connect(open, &QAction::triggered, this, [this, item] {
+        openDevice(item);
+    });
+
+    const QPersistentModelIndex persistentIndex(index);
+
+    QAction *teardown = m_placesModel->teardownActionForIndex(index);
+    QAction *eject = m_placesModel->ejectActionForIndex(index);
+    const bool setupNeeded = m_placesModel->setupNeeded(index);
+
+    if (teardown || eject || setupNeeded) {
+        menu->addSeparator();
+    }
+
+    if (setupNeeded) {
+        QAction *mount = menu->addAction(QIcon::fromTheme(QStringLiteral("media-mount")), i18nc("@action:inmenu", "Mount"));
+        connect(mount, &QAction::triggered, this, [this, persistentIndex] {
+            if (persistentIndex.isValid()) {
+                m_placesModel->requestSetup(persistentIndex);
+            }
+        });
+    }
+
+    if (teardown) {
+        teardown->setParent(menu);
+        connect(teardown, &QAction::triggered, this, [this, persistentIndex] {
+            if (persistentIndex.isValid()) {
+                m_placesModel->requestTeardown(persistentIndex);
+            }
+        });
+        menu->addAction(teardown);
+    }
+
+    if (eject) {
+        eject->setParent(menu);
+        connect(eject, &QAction::triggered, this, [this, persistentIndex] {
+            if (persistentIndex.isValid()) {
+                m_placesModel->requestEject(persistentIndex);
+            }
+        });
+        menu->addAction(eject);
+    }
+
+    if (!setupNeeded) {
+        menu->addSeparator();
+        QAction *properties = menu->addAction(QIcon::fromTheme(QStringLiteral("document-properties")), i18n("&Properties"));
+        connect(properties, &QAction::triggered, this, [url = m_placesModel->url(index)] {
+            KPropertiesDialog::showDialog(url, nullptr, false /*non modal*/);
+        });
+    }
+}
+
+bool FolderModel::isDeviceItem(const KFileItem &item)
+{
+    return item.url().scheme() == s_deviceScheme;
+}
